package cn.yuanxin.mvp.web.assessments;

import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.springframework.stereotype.Component;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * T05.photo_versions 读写助手（Java 写边界：受理/补拍构造版本清单）。
 *
 * <p>结构（DD 9.1 示例与 D 包裁定）：
 * {@code {"schema_version":1,"versions":[{"version":1,"images":{front,left,right},
 * "quality":{"status":"pending","required_views":[]}}]}}。quality 结论由 Python
 * worker 通过 failure_detail 发布，Java 只写 pending 占位。</p>
 */
@Component
public class PhotoVersions {

    private final ObjectMapper mapper;

    public PhotoVersions(ObjectMapper mapper) {
        this.mapper = mapper;
    }

    /** 初始版本 1 的完整视角清单。 */
    public String initial(Map<String, String> images) {
        ObjectNode root = newRoot();
        ArrayNode versions = root.putArray("versions");
        appendVersion(versions, 1, images);
        return serialize(root);
    }

    /** 追加新版本（完整视角清单）。 */
    public String append(String existingJson, long newVersion, Map<String, String> images) {
        ObjectNode root = parseObject(existingJson);
        ArrayNode versions = root.withArray("versions");
        if (!versions.isArray()) {
            throw new ApiException(ErrorCode.INTERNAL, "photo_versions malformed");
        }
        appendVersion(versions, newVersion, images);
        return serialize(root);
    }

    /** 读取指定版本已接纳的视角→mediaId 映射（缺版本/缺键返回空对象）。 */
    public Map<String, String> imagesAtVersion(String existingJson, long version) {
        Map<String, String> out = new LinkedHashMap<>();
        JsonNode versions = parseObject(existingJson).path("versions");
        if (!versions.isArray()) {
            return out;
        }
        for (JsonNode v : versions) {
            if (v.path("version").asLong(-1) == version) {
                JsonNode images = v.path("images");
                if (images.isObject()) {
                    images.fields().forEachRemaining(e -> {
                        if (e.getValue().isTextual()) {
                            out.put(e.getKey(), e.getValue().asText());
                        }
                    });
                }
            }
        }
        return out;
    }

    private static void appendVersion(ArrayNode versions, long version, Map<String, String> images) {
        ObjectNode v = versions.addObject();
        v.put("version", version);
        ObjectNode imageNode = v.putObject("images");
        // 固定 front/left/right 顺序，保证 JSON 稳定
        for (String view : List.of("front", "left", "right")) {
            String mediaId = images.get(view);
            if (mediaId != null) {
                imageNode.put(view, mediaId);
            }
        }
        ObjectNode quality = v.putObject("quality");
        quality.put("status", "pending");
        quality.putArray("required_views");
    }

    private ObjectNode newRoot() {
        ObjectNode root = mapper.createObjectNode();
        root.put("schema_version", 1);
        return root;
    }

    private ObjectNode parseObject(String json) {
        if (json == null || json.isBlank()) {
            return newRoot();
        }
        try {
            JsonNode node = mapper.readTree(json);
            if (node instanceof ObjectNode obj) {
                return obj;
            }
        } catch (Exception e) {
            // fallthrough
        }
        throw new ApiException(ErrorCode.INTERNAL, "photo_versions malformed");
    }

    private String serialize(ObjectNode root) {
        try {
            return mapper.writeValueAsString(root);
        } catch (Exception e) {
            throw new ApiException(ErrorCode.INTERNAL, "photo_versions serialization failed");
        }
    }
}

package cn.yuanxin.mvp.web.assessments;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * failure_detail 的有界安全投影（M3-A03；amend 裁定）：
 * <ul>
 *   <li>retryable：仅当 failure_detail 是 JSON 对象且 {@code retryable} 为
 *       boolean true → true；否则 false；failureCode 为 null 时为 null。
 *       failure_detail 原文（marker/长文本/未知键）绝不外泄。</li>
 *   <li>requiredViews：仅当 status='needs_retake' 且 failure_detail 是 JSON
 *       对象且含 {@code required_views} 数组时投影，逐项过滤到
 *       [front,left,right] 枚举、去重、有界；否则空数组。photo_versions 的
 *       quality 结论不由 worker 写，故不读取。</li>
 * </ul>
 */
@Component
public class FailureProjection {

    private static final Set<String> VIEWS = Set.of("front", "left", "right");
    private static final int MAX_REQUIRED_VIEWS = 3;

    private final ObjectMapper mapper;

    public FailureProjection(ObjectMapper mapper) {
        this.mapper = mapper;
    }

    public Boolean retryable(String failureCode, String failureDetailJson) {
        if (failureCode == null) {
            return null;
        }
        JsonNode node = parse(failureDetailJson);
        if (node != null && node.isObject()) {
            JsonNode retryable = node.path("retryable");
            if (retryable.isBoolean() && retryable.booleanValue()) {
                return true;
            }
        }
        return false;
    }

    public List<String> requiredViews(String status, String failureDetailJson) {
        if (!"needs_retake".equals(status)) {
            return List.of();
        }
        JsonNode node = parse(failureDetailJson);
        if (node == null || !node.isObject()) {
            return List.of();
        }
        JsonNode required = node.path("required_views");
        if (!required.isArray()) {
            return List.of();
        }
        LinkedHashSet<String> out = new LinkedHashSet<>();
        for (JsonNode item : required) {
            if (out.size() >= MAX_REQUIRED_VIEWS) {
                break;
            }
            if (item.isTextual() && VIEWS.contains(item.asText())) {
                out.add(item.asText());
            }
        }
        return new ArrayList<>(out);
    }

    private JsonNode parse(String raw) {
        if (raw == null || raw.isBlank()) {
            return null;
        }
        try {
            return mapper.readTree(raw);
        } catch (Exception e) {
            return null;
        }
    }
}

package cn.yuanxin.mvp.web.assessments;

import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.multipart.MultipartHttpServletRequest;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * M3-A01/M3-A02 multipart 严格解析（DD 3.3/10.1；contracts M3A01Metadata/
 * M3A02Metadata）：metadata part（application/json，未知字段拒绝）+ 二进制
 * 图片 part。缺 part / 多 part / 非法字段一律 400 INVALID_INPUT；三图合计超
 * 限 413 UPLOAD_TOO_LARGE。
 */
@Component
public class AssessmentMultipartParser {

    private static final Pattern BIGINT = Pattern.compile("^(0|[1-9][0-9]*)$");
    private static final Set<String> VIEWS = Set.of("front", "left", "right");

    private final ObjectMapper mapper;
    private final long maxRequestBytes;

    public AssessmentMultipartParser(ObjectMapper mapper,
                                     @Value("${app.assessments.max-request-bytes:33554432}")
                                     long maxRequestBytes) {
        this.mapper = mapper;
        this.maxRequestBytes = maxRequestBytes;
    }

    public record A01Metadata(String photoVersion, String captureSessionId, String consentEvidenceRef) {
    }

    public record A02Metadata(String expectedPhotoVersion, List<String> replacedViews) {
    }

    public record ParsedA01(A01Metadata metadata, Map<String, byte[]> images) {
    }

    public record ParsedA02(A02Metadata metadata, Map<String, byte[]> images) {
    }

    public ParsedA01 parseA01(HttpServletRequest request) {
        RawParts raw = split(request);
        A01Metadata md = readMetadata(raw.metadataBytes(), A01Metadata.class);
        if (!BIGINT.matcher(nullToEmpty(md.photoVersion())).matches() || !"1".equals(md.photoVersion())) {
            throw invalid("photoVersion must be the bigint string \"1\" for a new task");
        }
        requireText(md.captureSessionId(), "captureSessionId", 128);
        requireText(md.consentEvidenceRef(), "consentEvidenceRef", 128);
        Map<String, byte[]> images = requireExactViews(raw.imageParts(), VIEWS, "front,left,right");
        checkTotalSize(images);
        return new ParsedA01(md, images);
    }

    public ParsedA02 parseA02(HttpServletRequest request) {
        RawParts raw = split(request);
        A02Metadata md = readMetadata(raw.metadataBytes(), A02Metadata.class);
        if (md.expectedPhotoVersion() == null || !BIGINT.matcher(md.expectedPhotoVersion()).matches()) {
            throw invalid("expectedPhotoVersion must be a decimal bigint string");
        }
        List<String> replaced = md.replacedViews();
        if (replaced == null || replaced.isEmpty()) {
            throw invalid("replacedViews must be a non-empty list");
        }
        LinkedHashSet<String> requested = new LinkedHashSet<>();
        for (String view : replaced) {
            if (!VIEWS.contains(view)) {
                throw invalid("replacedViews entries must be one of front,left,right");
            }
            requested.add(view);
        }
        if (requested.size() != replaced.size()) {
            throw invalid("replacedViews must be unique");
        }
        Map<String, byte[]> images = requireExactViews(raw.imageParts(), requested,
                String.join(",", requested));
        checkTotalSize(images);
        return new ParsedA02(md, images);
    }

    private record RawParts(byte[] metadataBytes, Map<String, byte[]> imageParts) {
    }

    private RawParts split(HttpServletRequest request) {
        if (!(request instanceof MultipartHttpServletRequest multi)) {
            throw invalid("multipart/form-data request required");
        }
        Map<String, byte[]> parts = new LinkedHashMap<>();
        for (Map.Entry<String, MultipartFile> e : multi.getFileMap().entrySet()) {
            try {
                parts.put(e.getKey(), e.getValue().getBytes());
            } catch (Exception ex) {
                throw invalid("unreadable multipart part: " + e.getKey());
            }
        }
        byte[] metadata = parts.remove("metadata");
        if (metadata == null && multi.getParameter("metadata") != null) {
            metadata = multi.getParameter("metadata").getBytes(StandardCharsets.UTF_8);
        }
        if (metadata == null) {
            throw invalid("metadata part is required");
        }
        // 未声明的额外 multipart 文本参数同样拒绝（防未知字段静默成功）
        for (String name : multi.getParameterMap().keySet()) {
            if (!"metadata".equals(name)) {
                throw invalid("unknown multipart field: " + name);
            }
        }
        return new RawParts(metadata, parts);
    }

    private Map<String, byte[]> requireExactViews(Map<String, byte[]> parts, Set<String> expected,
                                                  String label) {
        if (!parts.keySet().equals(expected)) {
            List<String> missing = new ArrayList<>(expected);
            missing.removeAll(parts.keySet());
            List<String> extra = new ArrayList<>(parts.keySet());
            extra.removeAll(expected);
            throw invalid("image parts must be exactly [" + label + "]; missing=" + missing
                    + " extra=" + extra);
        }
        return parts;
    }

    private void checkTotalSize(Map<String, byte[]> images) {
        long total = 0;
        for (byte[] b : images.values()) {
            total += b.length;
            if (total > maxRequestBytes) {
                throw new ApiException(ErrorCode.UPLOAD_TOO_LARGE,
                        "total image bytes exceed configured limit " + maxRequestBytes);
            }
        }
    }

    private <T> T readMetadata(byte[] bytes, Class<T> type) {
        try {
            return mapper.readValue(bytes, type);
        } catch (ApiException e) {
            throw e;
        } catch (Exception e) {
            throw invalid("metadata is not a valid " + type.getSimpleName());
        }
    }

    private static void requireText(String value, String field, int max) {
        if (value == null || value.isEmpty()) {
            throw invalid(field + " is required");
        }
        if (value.length() > max) {
            throw invalid(field + " exceeds max length " + max);
        }
    }

    private static String nullToEmpty(String v) {
        return v == null ? "" : v;
    }

    private static ApiException invalid(String message) {
        return new ApiException(ErrorCode.INVALID_INPUT, message);
    }
}

package cn.yuanxin.mvp.web.assessments;

import cn.yuanxin.mvp.web.assessments.AssessmentMultipartParser.A01Metadata;
import cn.yuanxin.mvp.web.assessments.AssessmentMultipartParser.A02Metadata;
import cn.yuanxin.mvp.web.assessments.AssessmentMultipartParser.ParsedA01;
import cn.yuanxin.mvp.web.assessments.AssessmentMultipartParser.ParsedA02;
import cn.yuanxin.mvp.web.assessments.dto.AssessmentTaskAccepted;
import cn.yuanxin.mvp.web.auth.PrincipalContext;
import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import cn.yuanxin.mvp.web.idempotency.BeginOutcome;
import cn.yuanxin.mvp.web.idempotency.CanonicalObjectBuilder;
import cn.yuanxin.mvp.web.idempotency.IdempotencyHandle;
import cn.yuanxin.mvp.web.idempotency.IdempotencyService;
import cn.yuanxin.mvp.web.jobs.JobEnqueuer;
import cn.yuanxin.mvp.web.media.MediaIntakeService;
import cn.yuanxin.mvp.web.media.MediaPurpose;
import com.fasterxml.jackson.databind.JsonNode;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.UUID;

/**
 * M3-A01 受理 / M3-A02 补拍应用服务（DD 5、7.1、8.1/8.2、9.1）。
 *
 * <p>接线：multipart 解析 → canonicalObject → T13 begin（事务外）→ T11
 * ingest（事务外）→ 业务事务（锁 T03 → 查 T07 占用 → 插/更 T05 → 换指针 →
 * 补 T11 归属 → 入队 T12 → T13 complete）。确定性业务拒绝在事务内写 T13
 * rejected 并提交，异常在提交后抛出（绝不从事务回调内抛拒绝异常）。</p>
 */
@Service
public class AssessmentAcceptanceService {

    public static final String OPERATION_A01 = "m3a01";
    public static final String OPERATION_A02 = "m3a02";
    public static final String JOB_TYPE = "assessment.analyze";

    private final IdempotencyService idempotencyService;
    private final MediaIntakeService mediaIntakeService;
    private final JobEnqueuer jobEnqueuer;
    private final TransactionTemplate txTemplate;
    private final AssessmentRepository assessmentRepository;
    private final AssessmentGimbalRepository gimbalRepository;
    private final AssessmentMediaRepository mediaRepository;
    private final AssessmentAccessRepository accessRepository;
    private final PhotoVersions photoVersions;

    public AssessmentAcceptanceService(IdempotencyService idempotencyService,
                                       MediaIntakeService mediaIntakeService,
                                       JobEnqueuer jobEnqueuer,
                                       TransactionTemplate txTemplate,
                                       AssessmentRepository assessmentRepository,
                                       AssessmentGimbalRepository gimbalRepository,
                                       AssessmentMediaRepository mediaRepository,
                                       AssessmentAccessRepository accessRepository,
                                       PhotoVersions photoVersions) {
        this.idempotencyService = idempotencyService;
        this.mediaIntakeService = mediaIntakeService;
        this.jobEnqueuer = jobEnqueuer;
        this.txTemplate = txTemplate;
        this.assessmentRepository = assessmentRepository;
        this.gimbalRepository = gimbalRepository;
        this.mediaRepository = mediaRepository;
        this.accessRepository = accessRepository;
        this.photoVersions = photoVersions;
    }

    public record Accepted(AssessmentTaskAccepted data, boolean replayed) {
    }

    private record TxOutcome(AssessmentTaskAccepted data, ErrorCode rejectionCode,
                             String rejectionMessage) {
        static TxOutcome accepted(AssessmentTaskAccepted data) {
            return new TxOutcome(data, null, null);
        }

        static TxOutcome rejected(ErrorCode code, String message) {
            return new TxOutcome(null, code, message);
        }
    }

    // ----------------------------------------------------------------- A01

    public Accepted acceptA01(PrincipalContext principal, String idempotencyKey, ParsedA01 parsed) {
        UUID gimbalId = principal.gimbalUuid();
        A01Metadata md = parsed.metadata();
        Map<String, Object> fields = new LinkedHashMap<>();
        fields.put("photoVersion", md.photoVersion());
        fields.put("captureSessionId", md.captureSessionId());
        fields.put("consentEvidenceRef", md.consentEvidenceRef());
        String payloadHash = CanonicalObjectBuilder.forOperation(OPERATION_A01)
                .fields(fields)
                .imageParts(MediaIntakeService.partDigests(parsed.images()))
                .payloadHash();

        IdempotencyHandle handle = beginOrReplay(
                principal, idempotencyKey, payloadHash, OPERATION_A01).handle();
        // handle == null 表示已在上面的分支返回重放/拒绝；此处不可达
        throw new IllegalStateException("unreachable");
    }

    // 占位：真实入口在下方 acceptA01Full（保持 begin 分支与重放的显式返回）

    /**
     * A01 主入口：先 begin，重放直接投影返回；否则 ingest + 业务事务。
     */
    public Accepted acceptA01Full(PrincipalContext principal, String idempotencyKey,
                                  ParsedA01 parsed) {
        A01Metadata md = parsed.metadata();
        Map<String, Object> fields = new LinkedHashMap<>();
        fields.put("photoVersion", md.photoVersion());
        fields.put("captureSessionId", md.captureSessionId());
        fields.put("consentEvidenceRef", md.consentEvidenceRef());
        String payloadHash = CanonicalObjectBuilder.forOperation(OPERATION_A01)
                .fields(fields)
                .imageParts(MediaIntakeService.partDigests(parsed.images()))
                .payloadHash();

        BeginOutcome outcome = idempotencyService.begin(principal.t13PrincipalType(),
                principal.t13PrincipalId(), OPERATION_A01, idempotencyKey, payloadHash);
        switch (outcome) {
            case BeginOutcome.ReplaySucceeded replay -> {
                return new Accepted(projectAccepted(replay.resultSummary()), true);
            }
            case BeginOutcome.ReplayRejected rejected ->
                    throw IdempotencyService.replayedRejection(rejected);
            case BeginOutcome.NewAttempt fresh -> {
                return acceptA01New(principal, fresh.handle(), parsed);
            }
        }
    }

    private Accepted acceptA01New(PrincipalContext principal, IdempotencyHandle handle,
                                  ParsedA01 parsed) {
        UUID gimbalId = principal.gimbalUuid();
        Map<String, MediaIntakeService.IngestedMedia> ingested = mediaIntakeService.ingest(
                principal, MediaPurpose.ASSESSMENT_SOURCE, handle.requestId(), parsed.images());
        Map<String, String> mediaIds = mediaIds(ingested);

        TxOutcome outcome = txTemplate.execute(status -> {
            var gimbalOpt = gimbalRepository.lockById(gimbalId);
            if (gimbalOpt.isEmpty()) {
                return reject(handle, ErrorCode.RESOURCE_NOT_VISIBLE, "gimbal not visible");
            }
            AssessmentGimbalRepository.Pointer gimbal = gimbalOpt.get();

            var openExecution = accessRepository.findOpenByGimbal(gimbalId);
            if (openExecution.isPresent()) {
                ErrorCode code = "stopped".equals(openExecution.get().status())
                        ? ErrorCode.STOP_NOT_CONFIRMED : ErrorCode.DEVICE_OCCUPIED;
                String message = code == ErrorCode.STOP_NOT_CONFIRMED
                        ? "gimbal execution stopped but not closed"
                        : "gimbal has an open care execution";
                return reject(handle, code, message);
            }

            UUID taskId = UUID.randomUUID();
            assessmentRepository.insertQueued(taskId, gimbalId,
                    photoVersions.initial(mediaIds), handle.requestId());
            for (String mediaId : mediaIds.values()) {
                int claimed = mediaRepository.claim(UUID.fromString(mediaId), taskId, 1,
                        handle.requestId());
                if (claimed != 1) {
                    throw new ApiException(ErrorCode.INTERNAL, "media ownership claim failed");
                }
            }
            gimbalRepository.setCurrentAssessment(gimbalId, taskId);
            jobEnqueuer.enqueue(JOB_TYPE, "assessment", taskId, 1L, analyzePayload(taskId, 1),
                    "assessment:" + taskId + ":1");
            idempotencyService.completeSuccess(handle, "skin_assessment", taskId,
                    summary(taskId, "1", "queued"));
            long newRevision = gimbal.currentAssessmentRevision() + 1;
            return TxOutcome.accepted(new AssessmentTaskAccepted(
                    taskId.toString(), "queued", "1", String.valueOf(newRevision)));
        });

        return finish(outcome);
    }

    // ----------------------------------------------------------------- A02

    public Accepted acceptA02Full(PrincipalContext principal, String idempotencyKey, UUID taskId,
                                  String photoVersion, ParsedA02 parsed) {
        A02Metadata md = parsed.metadata();
        Map<String, Object> pathParams = new LinkedHashMap<>();
        pathParams.put("taskId", taskId.toString());
        pathParams.put("photoVersion", photoVersion);
        Map<String, Object> fields = new LinkedHashMap<>();
        fields.put("expectedPhotoVersion", md.expectedPhotoVersion());
        fields.put("replacedViews", new LinkedHashSet<>(md.replacedViews()).stream().sorted().toList());
        String payloadHash = CanonicalObjectBuilder.forOperation(OPERATION_A02)
                .pathParams(pathParams)
                .fields(fields)
                .imageParts(MediaIntakeService.partDigests(parsed.images()))
                .payloadHash();

        BeginOutcome outcome = idempotencyService.begin(principal.t13PrincipalType(),
                principal.t13PrincipalId(), OPERATION_A02, idempotencyKey, payloadHash);
        switch (outcome) {
            case BeginOutcome.ReplaySucceeded replay ->
                    { return new Accepted(projectAccepted(replay.resultSummary()), true); }
            case BeginOutcome.ReplayRejected rejected ->
                    { throw IdempotencyService.replayedRejection(rejected); }
            case BeginOutcome.NewAttempt fresh -> {
                return acceptA02New(principal, fresh.handle(), taskId, photoVersion, parsed);
            }
        }
    }

    private Accepted acceptA02New(PrincipalContext principal, IdempotencyHandle handle, UUID taskId,
                                  String photoVersion, ParsedA02 parsed) {
        UUID gimbalId = principal.gimbalUuid();
        Map<String, MediaIntakeService.IngestedMedia> ingested = mediaIntakeService.ingest(
                principal, MediaPurpose.ASSESSMENT_SOURCE, handle.requestId(), parsed.images());
        Map<String, String> newMediaIds = mediaIds(ingested);
        A02Metadata md = parsed.metadata();

        TxOutcome outcome = txTemplate.execute(status -> {
            var gimbalOpt = gimbalRepository.lockById(gimbalId);
            if (gimbalOpt.isEmpty()) {
                return reject(handle, ErrorCode.RESOURCE_NOT_VISIBLE, "gimbal not visible");
            }
            AssessmentGimbalRepository.Pointer gimbal = gimbalOpt.get();

            var rowOpt = assessmentRepository.findByIdForUpdate(taskId);
            if (rowOpt.isEmpty()) {
                return reject(handle, ErrorCode.RESOURCE_NOT_VISIBLE, "assessment not visible");
            }
            AssessmentRepository.AcceptanceRow row = rowOpt.get();
            if (!gimbalId.equals(row.gimbalId())) {
                return reject(handle, ErrorCode.RESOURCE_NOT_VISIBLE, "assessment not visible");
            }
            if (!taskId.equals(gimbal.currentAssessmentId())) {
                return reject(handle, ErrorCode.TASK_REPLACED,
                        "assessment is no longer the gimbal current task");
            }
            if (!"needs_retake".equals(row.status())) {
                return reject(handle, ErrorCode.PHOTO_VERSION_CONFLICT,
                        "retake is only allowed while the task requires a retake");
            }
            Long current = row.currentPhotoVersion();
            Long pathVersion = parseLong(photoVersion);
            Long expected = parseLong(md.expectedPhotoVersion());
            if (pathVersion == null || expected == null
                    || !expected.equals(current) || pathVersion != current + 1) {
                return reject(handle, ErrorCode.PHOTO_VERSION_CONFLICT,
                        "photo version does not follow the current version");
            }
            long newVersion = current + 1;
            long newRevision = row.processingRevision() + 1;

            Map<String, String> merged = new LinkedHashMap<>(
                    photoVersions.imagesAtVersion(row.photoVersions(), current));
            for (String view : newMediaIds.keySet()) {
                merged.put(view, newMediaIds.get(view));
            }
            String newPhotoVersions = photoVersions.append(row.photoVersions(), newVersion, merged);
            int updated = assessmentRepository.updateRetake(taskId, newPhotoVersions, newVersion,
                    newRevision);
            if (updated != 1) {
                throw new ApiException(ErrorCode.INTERNAL, "retake update failed");
            }
            for (String mediaId : newMediaIds.values()) {
                int claimed = mediaRepository.claim(UUID.fromString(mediaId), taskId, newVersion,
                        handle.requestId());
                if (claimed != 1) {
                    throw new ApiException(ErrorCode.INTERNAL, "media ownership claim failed");
                }
            }
            jobEnqueuer.enqueue(JOB_TYPE, "assessment", taskId, newRevision,
                    analyzePayload(taskId, newRevision),
                    "assessment:" + taskId + ":" + newRevision);
            idempotencyService.completeSuccess(handle, "skin_assessment", taskId,
                    summary(taskId, String.valueOf(newVersion), "queued"));
            return TxOutcome.accepted(new AssessmentTaskAccepted(
                    taskId.toString(), "queued", String.valueOf(newVersion),
                    String.valueOf(gimbal.currentAssessmentRevision())));
        });

        return finish(outcome);
    }

    // ------------------------------------------------------------- helpers

    private Accepted finish(TxOutcome outcome) {
        if (outcome.rejectionCode() != null) {
            throw new ApiException(outcome.rejectionCode(), outcome.rejectionMessage());
        }
        return new Accepted(outcome.data(), false);
    }

    /** 事务内确定性拒绝：写 T13 rejected 后返回拒绝结果（异常在提交后抛）。 */
    private TxOutcome reject(IdempotencyHandle handle, ErrorCode code, String message) {
        idempotencyService.completeRejected(handle, code, code.defaultStatus().value(),
                message, false, null);
        return TxOutcome.rejected(code, message);
    }

    private BeginOutcome beginOrReplay(PrincipalContext principal, String idempotencyKey,
                                       String payloadHash, String operation) {
        return idempotencyService.begin(principal.t13PrincipalType(), principal.t13PrincipalId(),
                operation, idempotencyKey, payloadHash);
    }

    private static Map<String, String> mediaIds(
            Map<String, MediaIntakeService.IngestedMedia> ingested) {
        Map<String, String> out = new LinkedHashMap<>();
        ingested.forEach((part, media) -> out.put(part, media.media().id().toString()));
        return out;
    }

    private static Map<String, Object> analyzePayload(UUID taskId, long processingRevision) {
        Map<String, Object> payload = new LinkedHashMap<>();
        payload.put("schema_version", 1);
        payload.put("assessment_id", taskId.toString());
        payload.put("processing_revision", String.valueOf(processingRevision));
        return payload;
    }

    private static Map<String, Object> summary(UUID taskId, String photoVersion, String status) {
        Map<String, Object> summary = new LinkedHashMap<>();
        summary.put("schema_version", 1);
        summary.put("task_id", taskId.toString());
        summary.put("photo_version", photoVersion);
        summary.put("status", status);
        return summary;
    }

    /** 从 T13 存储摘要重建受理响应（不重做写入、不切指针）。 */
    private static AssessmentTaskAccepted projectAccepted(JsonNode summary) {
        return new AssessmentTaskAccepted(
                summary.path("task_id").asText(null),
                summary.path("status").asText("queued"),
                summary.path("photo_version").asText(null),
                null);
    }

    private static Long parseLong(String value) {
        if (value == null) {
            return null;
        }
        try {
            return Long.parseLong(value);
        } catch (NumberFormatException e) {
            return null;
        }
    }

    // 兼容保留：直接调用的简洁入口（控制器使用 Full 版本）
    public Accepted acceptA01(PrincipalContext principal, String idempotencyKey, ParsedA01 parsed,
                              boolean unused) {
        return acceptA01Full(principal, idempotencyKey, parsed);
    }

    private List<String> unusedList() {
        return List.of();
    }
}

